sp_widget.client_script:
api.controller = function($scope, $timeout) {



    var c = this;





    /* =========================================================

       STATE

       ========================================================= */



    c.isEditing = false;

    c.isSaving = false;



    c.showSuccess = false;

    c.showError = false;



    c.successMessage = '';

    c.errorMessage = '';



    c.originalProfile = null;

    /* =========================================================
       SKILL CATALOG / ADD SKILL STATE
       ========================================================= */

    c.showAddSkillModal = false;
    c.selectedSkillIds = [];
    c.skillCatalogSearch = '';
    c.addSkillError = '';
    c.addSkillSuccess = '';
    c.isAddingSkills = false;







    /* =========================================================

       HELPER

       ========================================================= */



    function isStudent() {



        return (

            c.data &&

            c.data.profile &&

            c.data.profile.isStudent === true

        );

    }







    /* =========================================================

       START EDITING

       STUDENT ONLY

       ========================================================= */



    c.startEditing = function() {



        if (!isStudent()) {



            c.errorMessage =

                'Only students can edit their profile.';



            c.showError = true;



            return;

        }





        if (!c.data.profile) {



            c.errorMessage =

                'Profile information is not available.';



            c.showError = true;



            return;

        }





        /* -----------------------------------------------------

           CREATE BACKUP

           ----------------------------------------------------- */



        c.originalProfile =

            angular.copy(c.data.profile);





        c.isEditing = true;



        c.showSuccess = false;

        c.showError = false;

    };







    /* =========================================================

       CANCEL EDITING

       ========================================================= */



    c.cancelEditing = function() {



        if (c.originalProfile) {



            c.data.profile =

                angular.copy(c.originalProfile);

        }





        c.isEditing = false;



        c.isSaving = false;



        c.showError = false;



        c.showSuccess = false;

    };







    /* =========================================================

       CHECK WHETHER PROFILE CHANGED

       ========================================================= */



    c.hasChanges = function() {



        if (

            !c.originalProfile ||

            !c.data ||

            !c.data.profile

        ) {



            return false;

        }





        /*

         * These are the CLIENT-SIDE profile properties.

         *

         * The actual ServiceNow backend field names are

         * handled by the Server Script.

         */



        var fields = [



            /* -----------------------------------------------

               PERSONAL

               ----------------------------------------------- */



            'fullName',



            'email',



            'mobile',



            'gender',



            'fatherName',



            'fatherMobile',



            'address',



            'language',



            'alternateEmail',





            /* -----------------------------------------------

               ACADEMIC

               ----------------------------------------------- */



            'cgpa',



            'backlogs',





            /* -----------------------------------------------

               PROFESSIONAL

               ----------------------------------------------- */



            'skills',



            'git',



            'linkedin'



        ];





        for (var i = 0; i < fields.length; i++) {



            var field =

                fields[i];





            var oldValue =

                c.originalProfile[field];





            var newValue =

                c.data.profile[field];





            if (

                oldValue === null ||

                oldValue === undefined

            ) {



                oldValue = '';

            }





            if (

                newValue === null ||

                newValue === undefined

            ) {



                newValue = '';

            }





            if (

                String(oldValue) !==

                String(newValue)

            ) {



                return true;

            }

        }





        return false;

    };







    /* =========================================================

       VALIDATE STUDENT PROFILE

       ========================================================= */



    c.validateProfile = function() {



        var p =

            c.data &&

            c.data.profile;





        if (!p) {



            c.errorMessage =

                'Profile information is not available.';



            return false;

        }







        /* =====================================================

           STUDENT NAME

           ===================================================== */



        if (

            !p.fullName ||

            String(p.fullName).trim().length < 2

        ) {



            c.errorMessage =

                'Please enter a valid student name.';



            return false;

        }







        /* =====================================================

           EMAIL

           ===================================================== */



        if (

            !p.email ||

            !/^[^\s@]+@[^\s@]+\\.[^\s@]+$/.test(

                String(p.email).trim()

            )

        ) {



            c.errorMessage =

                'Please enter a valid email address.';



            return false;

        }







        /* =====================================================

           MOBILE

           ===================================================== */



        var mobile =

            String(p.mobile || '')

                .replace(/\s+/g, '')

                .replace(/[-()]/g, '');





        if (

            !mobile ||

            !/^[0-9]{10,15}$/.test(mobile)

        ) {



            c.errorMessage =

                'Please enter a valid mobile number.';



            return false;

        }







        /* =====================================================

           GENDER

           ===================================================== */



        if (!p.gender) {



            c.errorMessage =

                'Please select your gender.';



            return false;

        }







        /* =====================================================

           PARENT / GUARDIAN MOBILE

           ===================================================== */



        if (p.fatherMobile) {



            var fatherMobile =

                String(p.fatherMobile)

                    .replace(/\s+/g, '')

                    .replace(/[-()]/g, '');





            if (

                !/^[0-9]{10,15}$/.test(

                    fatherMobile

                )

            ) {



                c.errorMessage =

                    'Please enter a valid parent / guardian mobile number.';



                return false;

            }

        }







        /* =====================================================

           ALTERNATE EMAIL

           ===================================================== */



        if (p.alternateEmail) {



            if (

                !/^[^\s@]+@[^\s@]+\\.[^\s@]+$/.test(

                    String(p.alternateEmail).trim()

                )

            ) {



                c.errorMessage =

                    'Please enter a valid alternate email address.';



                return false;

            }

        }







        /* =====================================================

           CGPA

           ===================================================== */



        if (

            p.cgpa !== '' &&

            p.cgpa !== null &&

            p.cgpa !== undefined

        ) {



            var cgpa =

                parseFloat(p.cgpa);





            if (

                isNaN(cgpa) ||

                cgpa < 0 ||

                cgpa > 10

            ) {



                c.errorMessage =

                    'CGPA must be between 0 and 10.';



                return false;

            }

        }







        /* =====================================================

           BACKLOGS

           ===================================================== */



        if (

            p.backlogs !== '' &&

            p.backlogs !== null &&

            p.backlogs !== undefined

        ) {



            var backlogs =

                parseInt(p.backlogs, 10);





            if (

                isNaN(backlogs) ||

                backlogs < 0

            ) {



                c.errorMessage =

                    'Backlogs cannot be negative.';



                return false;

            }

        }







        /* =====================================================

           GITHUB

           ===================================================== */



        if (p.git) {



            if (

                String(p.git)

                    .toLowerCase()

                    .indexOf('github.com') === -1

            ) {



                c.errorMessage =

                    'Please enter a valid GitHub URL.';



                return false;

            }

        }







        /* =====================================================

           LINKEDIN

           ===================================================== */



        if (p.linkedin) {



            if (

                String(p.linkedin)

                    .toLowerCase()

                    .indexOf('linkedin.com') === -1

            ) {



                c.errorMessage =

                    'Please enter a valid LinkedIn URL.';



                return false;

            }

        }







        return true;

    };







    /* =========================================================

       UPDATE PROFILE

       STUDENT ONLY

       ========================================================= */



    c.updateProfile = function() {



        if (c.isSaving) {

            return;

        }





        /* -----------------------------------------------------

           ROLE CHECK

           ----------------------------------------------------- */



        if (!isStudent()) {



            c.errorMessage =

                'Only students can update their profile.';



            c.showError = true;



            return;

        }





        c.showSuccess = false;

        c.showError = false;







        /* -----------------------------------------------------

           CHECK WHETHER SOMETHING CHANGED

           ----------------------------------------------------- */



        if (!c.hasChanges()) {



            c.errorMessage =

                'No changes were made to your profile.';



            c.showError = true;



            return;

        }







        /* -----------------------------------------------------

           VALIDATE

           ----------------------------------------------------- */



        if (!c.validateProfile()) {



            c.showError = true;



            return;

        }







        c.isSaving = true;







        /* -----------------------------------------------------

           ACTION

           ----------------------------------------------------- */



        c.data.action =

            'update_profile';







        /* -----------------------------------------------------

           SEND PROFILE DATA

           ----------------------------------------------------- */



        c.data.profile =

            angular.copy(

                c.data.profile

            );







        /* =====================================================

           SERVER UPDATE

           ===================================================== */



        c.server.update().then(



            function(response) {



                c.isSaving = false;





                /* ---------------------------------------------

                   INVALID RESPONSE

                   --------------------------------------------- */



                if (

                    !response ||

                    !response.data

                ) {



                    c.errorMessage =

                        'Invalid response from server.';



                    c.showError = true;



                    return;

                }





                var result =

                    response.data;







                /* =================================================

                   SUCCESS

                   ================================================= */



                if (result.success === true) {





                    /* ---------------------------------------------

                       REFRESH PROFILE

                       --------------------------------------------- */



                    if (result.profile) {



                        c.data.profile =

                            angular.copy(

                                result.profile

                            );

                    }





                    /* ---------------------------------------------

                       RESET ORIGINAL COPY

                       --------------------------------------------- */



                    c.originalProfile =

                        angular.copy(

                            c.data.profile

                        );





                    /* ---------------------------------------------

                       EXIT EDIT MODE

                       --------------------------------------------- */



                    c.isEditing = false;





                    /* ---------------------------------------------

                       SUCCESS MESSAGE

                       --------------------------------------------- */



                    c.successMessage =

                        result.message ||

                        'Your profile has been updated successfully.';





                    c.showSuccess = true;





                    /* ---------------------------------------------

                       AUTO HIDE

                       --------------------------------------------- */



                    $timeout(function() {



                        c.showSuccess = false;



                    }, 5000);



                }





                /* =================================================

                   SERVER ERROR

                   ================================================= */



                else {



                    c.errorMessage =

                        result.message ||

                        result.error ||

                        'Unable to update your profile.';



                    c.showError = true;

                }



            },





            /* =====================================================

               REQUEST FAILURE

               ===================================================== */



            function() {



                c.isSaving = false;



                c.errorMessage =

                    'Unable to connect to the server. Please try again.';



                c.showError = true;

            }



        );

    };







        /* =========================================================
       ADD EXISTING SKILLS FROM SKILL CATALOG
       ========================================================= */

    c.openAddSkill = function() {
        if (!isStudent()) { return; }
        c.selectedSkillIds = [];
        c.skillCatalogSearch = '';
        c.addSkillError = '';
        c.addSkillSuccess = '';
        c.isAddingSkills = false;
        c.showAddSkillModal = true;
    };

    c.closeAddSkill = function(event) {
        if (event && event.target !== event.currentTarget) { return; }
        if (c.isAddingSkills) { return; }
        c.showAddSkillModal = false;
        c.selectedSkillIds = [];
        c.skillCatalogSearch = '';
        c.addSkillError = '';
        c.addSkillSuccess = '';
    };

    c.isExistingSkill = function(sysId) {
        var list = c.data && c.data.profile && c.data.profile.skillList ? c.data.profile.skillList : [];
        for (var i = 0; i < list.length; i++) {
            if (String(list[i].sys_id) === String(sysId)) { return true; }
        }
        return false;
    };

    c.isSkillSelected = function(sysId) {
        return c.selectedSkillIds.indexOf(String(sysId)) !== -1;
    };

    c.toggleSkillSelection = function(skill, event) {
        if (!skill || c.isExistingSkill(skill.sys_id) || c.isAddingSkills) { return; }
        if (event) { event.stopPropagation(); }
        var id = String(skill.sys_id);
        var index = c.selectedSkillIds.indexOf(id);
        if (index === -1) { c.selectedSkillIds.push(id); }
        else { c.selectedSkillIds.splice(index, 1); }
    };

    c.addSelectedSkills = function() {
        if (c.isAddingSkills) { return; }
        if (!isStudent()) { c.addSkillError = 'Only students can add skills.'; return; }
        if (!c.selectedSkillIds.length) { c.addSkillError = 'Please select at least one skill.'; return; }

        c.addSkillError = '';
        c.addSkillSuccess = '';
        c.isAddingSkills = true;
        c.data.action = 'add_skills';
        c.data.selectedSkillIds = angular.copy(c.selectedSkillIds);

        c.server.update().then(function(response) {
            c.isAddingSkills = false;
            var result = response && response.data ? response.data : response;
            if (!result) { c.addSkillError = 'Invalid response from server.'; return; }

            if (result.success === true && result.skillsAdded === true) {
                c.addSkillSuccess = result.message || 'Selected skills were added successfully.';
                if (result.profile) {
                    c.data.profile = angular.copy(result.profile);
                    c.originalProfile = angular.copy(c.data.profile);
                } else {
                    c.server.get().then(function(refreshResponse) {
                        var refresh = refreshResponse && refreshResponse.data ? refreshResponse.data : refreshResponse;
                        if (refresh && refresh.profile) {
                            c.data.profile = angular.copy(refresh.profile);
                            c.originalProfile = angular.copy(c.data.profile);
                        }
                    });
                }
                c.selectedSkillIds = [];
                $timeout(function() {
                    c.showAddSkillModal = false;
                    c.addSkillSuccess = '';
                }, 900);
            } else {
                c.addSkillError = result.message || result.error || 'Unable to add the selected skills.';
            }
        }, function() {
            c.isAddingSkills = false;
            c.addSkillError = 'Unable to connect to the server. Please try again.';
        });
    };



/* =========================================================
       REQUEST A SKILL
       ========================================================= */

    c.openSkillRequest = function() {

        if (!isStudent()) {
            return;
        }

        c.skillRequest = { requestedTerm: '' };
        c.skillRequestError = '';
        c.skillRequestSuccess = '';
        c.isSubmittingSkillRequest = false;
        c.showSkillRequestModal = true;
    };


    c.closeSkillRequest = function(event) {

        if (event && event.target !== event.currentTarget) {
            return;
        }

        if (c.isSubmittingSkillRequest) {
            return;
        }

        c.showSkillRequestModal = false;
        c.skillRequestError = '';
        c.skillRequestSuccess = '';
    };


    c.submitSkillRequest = function() {

        if (c.isSubmittingSkillRequest) {
            return;
        }

        if (!isStudent()) {
            c.skillRequestError = 'Only students can request a skill.';
            return;
        }

        var term = String(
            c.skillRequest && c.skillRequest.requestedTerm || ''
        ).trim();

        if (!term) {
            c.skillRequestError = 'Please enter a skill name.';
            return;
        }

        c.skillRequestError = '';
        c.skillRequestSuccess = '';
        c.isSubmittingSkillRequest = true;

        c.data.action = 'request_skill';
        c.data.skillRequest = { requestedTerm: term };

        c.server.update().then(
            function(response) {

                c.isSubmittingSkillRequest = false;

                /* Service Portal can expose the server payload either as
                   response.data or directly as response. */
                var result =
                    response && response.data
                        ? response.data
                        : response;

                if (!result) {
                    c.skillRequestError = 'Invalid response from server.';
                    return;
                }

                if (result.success === true && result.skillRequestCreated === true) {

                    c.skillRequestSuccess =
                        result.message ||
                        'Skill request submitted successfully.';

                    c.server.get().then(function(refreshResponse) {
                        if (refreshResponse && refreshResponse.data && refreshResponse.data.profile) {
                            c.data.profile = angular.copy(refreshResponse.data.profile);
                            c.originalProfile = angular.copy(c.data.profile);
                        }
                    });

                    $timeout(function() {
                        c.showSkillRequestModal = false;
                        c.skillRequestSuccess = '';
                    }, 1400);

                } else {
                    c.skillRequestError =
                        result.message ||
                        result.error ||
                        'Unable to submit the skill request.';
                }
            },
            function() {
                c.isSubmittingSkillRequest = false;
                c.skillRequestError =
                    'Unable to connect to the server. Please try again.';
            }
        );
    };



/* =========================================================

       CLOSE ALERTS

       ========================================================= */



    c.closeAlert = function(type) {



        if (type === 'success') {



            c.showSuccess = false;

        }





        if (type === 'error') {



            c.showError = false;

        }

    };







    /* =========================================================

       GET INITIAL

       ========================================================= */



    c.getInitial = function(name) {



        if (!name) {

            return 'U';

        }





        var value =

            String(name).trim();





        if (!value) {

            return 'U';

        }





        return value

            .charAt(0)

            .toUpperCase();

    };







    /* =========================================================

       DISPLAY VALUE

       ========================================================= */



    c.getDisplayValue = function(value) {



        if (

            value === null ||

            value === undefined ||

            value === ''

        ) {



            return '—';

        }





        return value;

    };







    /* =========================================================

       OPEN EXTERNAL LINK

       ========================================================= */



    c.openExternalLink = function(url) {



        if (!url) {

            return;

        }





        window.open(

            url,

            '\_blank'

        );

    };







    /* =========================================================

       NORMALIZE PROFILE

       ========================================================= */



    c.normalizeProfile = function() {



        if (!c.data) {

            c.data = {};

        }





        if (!c.data.profile) {

            c.data.profile = {};

        }





        var p =

            c.data.profile;







        /* =====================================================

           COMMON ROLE FIELDS

           ===================================================== */



        var fields = [



            'fullName',



            'studentId',

            'registerNumber',



            'email',

            'mobile',

            'gender',



            'fatherName',

            'fatherMobile',



            'address',

            'language',

            'alternateEmail',



            'collegeName',

            'branch',



            'cgpa',

            'backlogs',



            'currentYear',

            'passingYear',



            'skills',



            'git',

            'linkedin',



            'resume',



            'eligible',

            'placementStatus',



            'username',

            'userName',



            'title',

            'department',

            'company',

            'location',

            'manager',



            'role',

            'roleDescription',



            'status',

            'createdOn',



            'completion'



        ];





        for (

            var i = 0;

            i < fields.length;

            i++

        ) {



            var field =

                fields[i];





            if (

                p[field] === null ||

                p[field] === undefined

            ) {



                p[field] = '';

            }

        }







        /* =====================================================

           ROLE FLAGS



           Server Script should normally provide these.

           ===================================================== */



        if (

            p.isStudent === undefined

        ) {



            p.isStudent = false;

        }





        if (

            p.isOfficer === undefined

        ) {



            p.isOfficer = false;

        }





        if (

            p.isAdmin === undefined

        ) {



            p.isAdmin = false;

        }





        if (

            p.isInterviewer === undefined

        ) {



            p.isInterviewer = false;

        }







        /* =====================================================

           STATISTICS OBJECT

           ===================================================== */



        if (

            !p.statistics ||

            typeof p.statistics !== 'object'

        ) {



            p.statistics = {};

        }





        var statistics = [



            'drivesManaged',



            'applicationsReviewed',



            'studentsManaged',



            'interviewsAssigned',



            'interviewsCompleted',



            'pendingEvaluations',



            'selectedCandidates',



            'offers'



        ];





        for (

            var j = 0;

            j < statistics.length;

            j++

        ) {



            var statistic =

                statistics[j];





            if (

                p.statistics[statistic] ===

                null ||

                p.statistics[statistic] ===

                undefined

            ) {



                p.statistics[statistic] = 0;

            }

        }







        /* =====================================================

           KEEP ORIGINAL PROFILE

           ===================================================== */



        c.originalProfile =

            angular.copy(p);

    };







    /* =========================================================

       INITIALIZATION

       ========================================================= */



    c.$onInit = function() {



        if (!c.data) {

            c.data = {};

        }





        if (!c.data.profile) {

            c.data.profile = {};

        }





        c.normalizeProfile();

    };







    /* =========================================================

       FALLBACK INITIALIZATION

       ========================================================= */



    if (c.data) {



        c.normalizeProfile();

    }



};

sp_widget.css:
/* ============================================================
   NEXORA — MY PROFILE
   NAVY + CORAL ENTERPRISE THEME
   ============================================================ */


/* ============================================================
   ROOT
   ============================================================ */

.nx-profile-page {

    width: 100%;

    min-height: 100vh;

    padding: 32px 42px 60px;

    background:
        #f5f7fa;

    color:
        #172b3f;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;

    box-sizing:
        border-box;
}


/* ============================================================
   HERO
   ============================================================ */

.nx-profile-hero {

    position:
        relative;

    overflow:
        hidden;

    max-width:
        1500px;

    margin:
        0 auto 28px;

    min-height:
        220px;

    border-radius:
        24px;

    background:
        linear-gradient(
            135deg,
            #17334b 0%,
            #1b3b55 52%,
            #20435d 100%
        );

    box-shadow:
        0 18px 45px rgba(23, 51, 75, 0.15);

}


.nx-hero-pattern {

    position:
        absolute;

    inset:
        0;

    pointer-events:
        none;

    opacity:
        .35;

    background-image:

        radial-gradient(
            circle at 15% 20%,
            rgba(255,255,255,.10) 0,
            rgba(255,255,255,.10) 1px,
            transparent 2px
        );

    background-size:
        28px 28px;
}


.nx-profile-hero::after {

    content:
        "";

    position:
        absolute;

    width:
        320px;

    height:
        320px;

    right:
        -110px;

    top:
        -170px;

    border-radius:
        50%;

    background:
        rgba(255,107,91,.15);

}


.nx-profile-hero-content {

    position:
        relative;

    z-index:
        2;

    display:
        flex;

    align-items:
        center;

    gap:
        26px;

    min-height:
        220px;

    padding:
        38px 42px;

    box-sizing:
        border-box;
}


/* ============================================================
   AVATAR
   ============================================================ */

.nx-profile-avatar-wrap {

    position:
        relative;

    flex:
        0 0 auto;
}


.nx-profile-avatar {

    width:
        92px;

    height:
        92px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border:
        4px solid rgba(255,255,255,.18);

    border-radius:
        24px;

    background:
        linear-gradient(
            135deg,
            #ff6b5b,
            #ff8578
        );

    color:
        #ffffff;

    font-size:
        34px;

    font-weight:
        800;

    box-shadow:
        0 12px 30px rgba(0,0,0,.18);
}


.nx-online-dot {

    position:
        absolute;

    right:
        -2px;

    bottom:
        2px;

    width:
        18px;

    height:
        18px;

    border:
        4px solid #17334b;

    border-radius:
        50%;

    background:
        #39c98b;
}


.nx-online-dot.nx-offline {

    background:
        #9aa7b3;
}


/* ============================================================
   HERO IDENTITY
   ============================================================ */

.nx-profile-identity {

    min-width:
        0;

    flex:
        1;
}


.nx-profile-eyebrow {

    display:
        flex;

    align-items:
        center;

    gap:
        8px;

    margin-bottom:
        8px;

    color:
        #ff9a8e;

    font-size:
        11px;

    font-weight:
        800;

    letter-spacing:
        1.8px;
}


.nx-profile-identity h1 {

    margin:
        0;

    color:
        #ffffff;

    font-size:
        34px;

    line-height:
        1.15;

    font-weight:
        800;

    letter-spacing:
        -.7px;

    word-break:
        break-word;
}


.nx-profile-role {

    display:
        flex;

    flex-wrap:
        wrap;

    align-items:
        center;

    gap:
        10px;

    margin-top:
        14px;
}


.nx-role-pill {

    display:
        inline-flex;

    align-items:
        center;

    gap:
        7px;

    padding:
        7px 13px;

    border:
        1px solid rgba(255,255,255,.14);

    border-radius:
        999px;

    background:
        rgba(255,255,255,.10);

    color:
        #ffffff;

    font-size:
        12px;

    font-weight:
        700;

    backdrop-filter:
        blur(8px);
}


.nx-status-pill {

    display:
        inline-flex;

    align-items:
        center;

    gap:
        7px;

    padding:
        7px 12px;

    border-radius:
        999px;

    font-size:
        11px;

    font-weight:
        700;
}


.nx-status-active {

    background:
        rgba(57,201,139,.14);

    color:
        #8ff0c3;
}


.nx-status-inactive {

    background:
        rgba(255,255,255,.10);

    color:
        #c5cdd5;
}


.nx-status-dot {

    width:
        7px;

    height:
        7px;

    border-radius:
        50%;

    background:
        currentColor;
}


.nx-profile-description {

    max-width:
        680px;

    margin:
        13px 0 0;

    color:
        rgba(255,255,255,.68);

    font-size:
        13px;

    line-height:
        1.6;
}


/* ============================================================
   HERO ACTION
   ============================================================ */

.nx-profile-hero-action {

    flex:
        0 0 auto;

    align-self:
        center;
}


.nx-edit-btn {

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    gap:
        9px;

    min-width:
        145px;

    padding:
        13px 20px;

    border:
        0;

    border-radius:
        12px;

    background:
        #ff6b5b;

    color:
        #ffffff;

    font-size:
        13px;

    font-weight:
        750;

    cursor:
        pointer;

    box-shadow:
        0 8px 22px rgba(255,107,91,.25);

    transition:
        all .2s ease;
}


.nx-edit-btn:hover {

    transform:
        translateY(-2px);

    background:
        #ff7769;

    box-shadow:
        0 12px 28px rgba(255,107,91,.32);
}


.nx-editing-badge {

    display:
        inline-flex;

    align-items:
        center;

    gap:
        8px;

    padding:
        11px 15px;

    border:
        1px solid rgba(255,255,255,.15);

    border-radius:
        12px;

    background:
        rgba(255,255,255,.08);

    color:
        #ffffff;

    font-size:
        12px;

    font-weight:
        700;
}


/* ============================================================
   ALERTS
   ============================================================ */

.nx-alert {

    max-width:
        1500px;

    margin:
        0 auto 20px;

    display:
        flex;

    align-items:
        center;

    gap:
        13px;

    padding:
        14px 16px;

    border:
        1px solid;

    border-radius:
        14px;

    box-sizing:
        border-box;
}


.nx-alert-success {

    border-color:
        #b9ead5;

    background:
        #effbf6;

    color:
        #176847;
}


.nx-alert-error {

    border-color:
        #f1c4be;

    background:
        #fff5f3;

    color:
        #9c3429;
}


.nx-alert-icon {

    width:
        34px;

    height:
        34px;

    flex:
        0 0 34px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        10px;

    background:
        rgba(255,255,255,.75);
}


.nx-alert-content {

    display:
        flex;

    flex-direction:
        column;

    gap:
        2px;

    flex:
        1;
}


.nx-alert-content strong {

    font-size:
        13px;
}


.nx-alert-content span {

    font-size:
        12px;

    opacity:
        .85;
}


.nx-alert-close {

    border:
        0;

    background:
        transparent;

    cursor:
        pointer;

    color:
        inherit;

    opacity:
        .6;
}


/* ============================================================
   MAIN
   ============================================================ */

.nx-profile-content {

    max-width:
        1500px;

    margin:
        0 auto;
}


/* ============================================================
   CARDS
   ============================================================ */

.nx-card {

    margin-bottom:
        22px;

    padding:
        26px;

    border:
        1px solid #e4e9ef;

    border-radius:
        18px;

    background:
        #ffffff;

    box-shadow:
        0 8px 28px rgba(22,43,63,.055);

    box-sizing:
        border-box;

    transition:
        box-shadow .2s ease,
        transform .2s ease;
}


.nx-card:hover {

    box-shadow:
        0 12px 34px rgba(22,43,63,.075);
}


/* ============================================================
   CARD HEADER
   ============================================================ */

.nx-card-header {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap:
        20px;

    margin-bottom:
        24px;
}


.nx-card-heading {

    display:
        flex;

    align-items:
        center;

    gap:
        13px;
}


.nx-card-heading h2 {

    margin:
        0;

    color:
        #172b3f;

    font-size:
        18px;

    font-weight:
        800;
}


.nx-card-heading p {

    margin:
        4px 0 0;

    color:
        #7a8998;

    font-size:
        12px;
}


.nx-section-icon {

    width:
        42px;

    height:
        42px;

    flex:
        0 0 42px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        12px;

    font-size:
        16px;
}


.nx-icon-coral {

    background:
        #fff0ed;

    color:
        #ff6b5b;
}


.nx-icon-blue {

    background:
        #edf5ff;

    color:
        #3e7fc2;
}


.nx-icon-purple {

    background:
        #f2edff;

    color:
        #7656c9;
}


.nx-icon-green {

    background:
        #eafaf3;

    color:
        #25a873;
}


.nx-icon-orange {

    background:
        #fff5e8;

    color:
        #db8a24;
}


.nx-icon-slate {

    background:
        #eef2f5;

    color:
        #536779;
}


/* ============================================================
   COMPLETION
   ============================================================ */

.nx-completion-card {

    background:
        linear-gradient(
            135deg,
            #ffffff,
            #fbfcfe
        );
}


.nx-completion-number {

    color:
        #ff6b5b;

    font-size:
        24px;

    font-weight:
        800;
}


.nx-progress-track {

    height:
        9px;

    overflow:
        hidden;

    border-radius:
        999px;

    background:
        #e9edf2;
}


.nx-progress-fill {

    height:
        100%;

    border-radius:
        inherit;

    background:
        linear-gradient(
            90deg,
            #ff6b5b,
            #ff887b
        );

    transition:
        width .4s ease;
}


.nx-completion-footer {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap:
        15px;

    margin-top:
        12px;

    color:
        #7a8998;

    font-size:
        11px;
}


.nx-completion-footer i {

    color:
        #39b981;

    margin-right:
        4px;
}


/* ============================================================
   FORM GRID
   ============================================================ */

.nx-form-grid {

    display:
        grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap:
        20px 22px;
}


.nx-field {

    min-width:
        0;
}


.nx-field-full {

    grid-column:
        1 / -1;
}


.nx-field label {

    display:
        block;

    margin-bottom:
        8px;

    color:
        #425466;

    font-size:
        11px;

    font-weight:
        750;

    letter-spacing:
        .2px;
}


.nx-input-wrap {

    position:
        relative;
}


.nx-input-wrap > i {

    position:
        absolute;

    left:
        14px;

    top:
        50%;

    z-index:
        2;

    transform:
        translateY(-50%);

    color:
        #92a0ad;

    font-size:
        13px;

    pointer-events:
        none;
}


.nx-input-wrap input,
.nx-input-wrap select,
.nx-input-wrap textarea {

    width:
        100%;

    border:
        1px solid #dfe5eb;

    border-radius:
        11px;

    outline:
        none;

    background:
        #f9fafb;

    color:
        #263b4d;

    font-family:
        inherit;

    font-size:
        13px;

    box-sizing:
        border-box;

    transition:
        all .18s ease;
}


.nx-input-wrap input,
.nx-input-wrap select {

    height:
        45px;

    padding:
        0 13px 0 40px;
}


.nx-input-wrap textarea {

    min-height:
        95px;

    padding:
        13px 13px 13px 40px;

    resize:
        vertical;

    line-height:
        1.5;
}


.nx-input-wrap input:focus,
.nx-input-wrap select:focus,
.nx-input-wrap textarea:focus {

    border-color:
        #ff8a7d;

    background:
        #ffffff;

    box-shadow:
        0 0 0 3px rgba(255,107,91,.09);
}


.nx-input-wrap input:disabled,
.nx-input-wrap select:disabled,
.nx-input-wrap textarea:disabled {

    cursor:
        default;

    color:
        #394e60;

    background:
        #f7f8fa;

    border-color:
        #e5e9ee;

    opacity:
        1;
}


/* ============================================================
   READ ONLY LABEL
   ============================================================ */

.nx-readonly-label {

    display:
        inline-flex;

    align-items:
        center;

    gap:
        6px;

    padding:
        7px 10px;

    border-radius:
        8px;

    background:
        #f2f5f7;

    color:
        #728190;

    font-size:
        10px;

    font-weight:
        750;
}


/* ============================================================
   INFO GRID
   ============================================================ */

.nx-info-grid {

    display:
        grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap:
        1px;

    overflow:
        hidden;

    border:
        1px solid #e6ebf0;

    border-radius:
        13px;

    background:
        #e6ebf0;
}


.nx-info-grid-three {

    grid-template-columns:
        repeat(3, minmax(0, 1fr));
}


.nx-info-item {

    min-width:
        0;

    min-height:
        78px;

    padding:
        17px;

    background:
        #ffffff;

    box-sizing:
        border-box;
}


.nx-info-item span {

    display:
        block;

    margin-bottom:
        8px;

    color:
        #8996a3;

    font-size:
        10px;

    font-weight:
        700;

    text-transform:
        uppercase;

    letter-spacing:
        .55px;
}


.nx-info-item strong {

    display:
        block;

    overflow:
        hidden;

    color:
        #253b4d;

    font-size:
        13px;

    font-weight:
        700;

    text-overflow:
        ellipsis;

    white-space:
        nowrap;
}


.nx-highlight-value {

    color:
        #ff6b5b !important;
}


/* ============================================================
   PROFESSIONAL LINKS
   ============================================================ */

.nx-link-button {

    margin-top:
        8px;

    padding:
        0;

    border:
        0;

    background:
        transparent;

    color:
        #3676b5;

    font-size:
        11px;

    font-weight:
        700;

    cursor:
        pointer;
}


.nx-link-button:hover {

    color:
        #ff6b5b;

    text-decoration:
        underline;
}


/* ============================================================
   RESUME
   ============================================================ */

.nx-resume-box {

    display:
        flex;

    align-items:
        center;

    gap:
        13px;

    padding:
        14px;

    border:
        1px solid #e5eaf0;

    border-radius:
        12px;

    background:
        #fafbfc;
}


.nx-resume-icon {

    width:
        42px;

    height:
        42px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        10px;

    background:
        #fff0ed;

    color:
        #e45c4e;

    font-size:
        17px;
}


.nx-resume-info {

    display:
        flex;

    flex-direction:
        column;

    min-width:
        0;

    gap:
        3px;
}


.nx-resume-info strong {

    overflow:
        hidden;

    color:
        #304658;

    font-size:
        12px;

    text-overflow:
        ellipsis;

    white-space:
        nowrap;
}


.nx-resume-info span {

    color:
        #8b98a4;

    font-size:
        10px;
}


/* ============================================================
   PLACEMENT
   ============================================================ */

.nx-placement-grid {

    display:
        grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap:
        16px;
}


.nx-placement-item {

    padding:
        20px;

    border:
        1px solid #e6ebf0;

    border-radius:
        13px;

    background:
        #fbfcfd;
}


.nx-placement-item span {

    display:
        block;

    margin-bottom:
        8px;

    color:
        #8996a3;

    font-size:
        10px;

    font-weight:
        750;

    text-transform:
        uppercase;

    letter-spacing:
        .5px;
}


.nx-placement-item strong {

    color:
        #263d4f;

    font-size:
        17px;

    font-weight:
        800;
}


.nx-value-success {

    color:
        #20a46f !important;
}


.nx-value-warning {

    color:
        #d98522 !important;
}


/* ============================================================
   EDIT ACTIONS
   ============================================================ */

.nx-edit-actions {

    position:
        sticky;

    bottom:
        20px;

    z-index:
        20;

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap:
        20px;

    margin:
        5px 0 24px;

    padding:
        14px 17px;

    border:
        1px solid #dfe5eb;

    border-radius:
        15px;

    background:
        rgba(255,255,255,.94);

    box-shadow:
        0 12px 35px rgba(20,40,60,.13);

    backdrop-filter:
        blur(12px);
}


.nx-edit-note {

    display:
        flex;

    align-items:
        center;

    gap:
        8px;

    color:
        #748291;

    font-size:
        11px;
}


.nx-edit-note i {

    color:
        #4d7ca5;
}


.nx-edit-buttons {

    display:
        flex;

    gap:
        10px;
}


.nx-secondary-btn,
.nx-save-btn {

    min-width:
        120px;

    height:
        42px;

    padding:
        0 17px;

    border-radius:
        10px;

    font-size:
        12px;

    font-weight:
        750;

    cursor:
        pointer;

    transition:
        all .18s ease;
}


.nx-secondary-btn {

    border:
        1px solid #d8dfe6;

    background:
        #ffffff;

    color:
        #526372;
}


.nx-secondary-btn:hover {

    background:
        #f5f7f9;
}


.nx-save-btn {

    border:
        0;

    background:
        #ff6b5b;

    color:
        #ffffff;

    box-shadow:
        0 7px 18px rgba(255,107,91,.22);
}


.nx-save-btn:hover:not(:disabled) {

    background:
        #f95f50;

    transform:
        translateY(-1px);
}


.nx-save-btn:disabled,
.nx-secondary-btn:disabled {

    cursor:
        not-allowed;

    opacity:
        .55;

    transform:
        none;
}


/* ============================================================
   STAFF PROFILE
   ============================================================ */

.nx-staff-overview {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    gap:
        35px;

    padding:
        28px;

    background:
        linear-gradient(
            135deg,
            #ffffff,
            #f8fafc
        );
}


.nx-staff-main {

    display:
        flex;

    align-items:
        center;

    gap:
        18px;

    min-width:
        0;
}


.nx-staff-avatar {

    width:
        76px;

    height:
        76px;

    flex:
        0 0 76px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        20px;

    background:
        #17334b;

    color:
        #ffffff;

    font-size:
        28px;

    font-weight:
        800;
}


.nx-staff-label {

    display:
        block;

    margin-bottom:
        5px;

    color:
        #ff6b5b;

    font-size:
        10px;

    font-weight:
        800;

    letter-spacing:
        1.2px;
}


.nx-staff-main h2 {

    margin:
        0;

    color:
        #1c3346;

    font-size:
        22px;

    font-weight:
        800;
}


.nx-staff-main p {

    max-width:
        600px;

    margin:
        6px 0 0;

    color:
        #778695;

    font-size:
        12px;

    line-height:
        1.5;
}


.nx-staff-meta {

    display:
        grid;

    grid-template-columns:
        repeat(3, minmax(110px, 1fr));

    gap:
        22px;

    flex:
        0 0 48%;
}


.nx-staff-meta span {

    display:
        block;

    margin-bottom:
        6px;

    color:
        #929eaa;

    font-size:
        9px;

    font-weight:
        750;

    text-transform:
        uppercase;

    letter-spacing:
        .5px;
}


.nx-staff-meta strong {

    display:
        block;

    overflow:
        hidden;

    color:
        #30485a;

    font-size:
        12px;

    text-overflow:
        ellipsis;

    white-space:
        nowrap;
}


/* ============================================================
   STAFF STATISTICS
   ============================================================ */

.nx-stats-grid {

    display:
        grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap:
        14px;
}


.nx-stat-card {

    display:
        flex;

    align-items:
        center;

    gap:
        13px;

    min-height:
        88px;

    padding:
        16px;

    border:
        1px solid #e6ebf0;

    border-radius:
        14px;

    background:
        #ffffff;

    box-sizing:
        border-box;

    transition:
        all .2s ease;
}


.nx-stat-card:hover {

    transform:
        translateY(-2px);

    box-shadow:
        0 8px 22px rgba(25,45,65,.08);
}


.nx-stat-icon {

    width:
        42px;

    height:
        42px;

    flex:
        0 0 42px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        11px;

    font-size:
        15px;
}


.nx-stat-blue {

    background:
        #edf5ff;

    color:
        #3c79b6;
}


.nx-stat-coral {

    background:
        #fff0ed;

    color:
        #ff6b5b;
}


.nx-stat-purple {

    background:
        #f2edff;

    color:
        #7656c9;
}


.nx-stat-orange {

    background:
        #fff4e6;

    color:
        #db8a24;
}


.nx-stat-green {

    background:
        #eafaf3;

    color:
        #25a873;
}


.nx-stat-yellow {

    background:
        #fff8df;

    color:
        #c99a18;
}


.nx-stat-teal {

    background:
        #e8f8f7;

    color:
        #218f88;
}


.nx-stat-indigo {

    background:
        #eeefff;

    color:
        #5962b5;
}


.nx-stat-card span {

    display:
        block;

    margin-bottom:
        5px;

    color:
        #8593a0;

    font-size:
        10px;

    font-weight:
        700;
}


.nx-stat-card strong {

    display:
        block;

    color:
        #20394d;

    font-size:
        22px;

    line-height:
        1;

    font-weight:
        800;
}


/* ============================================================
   EMPTY STATE
   ============================================================ */

.nx-empty-profile {

    display:
        flex;

    flex-direction:
        column;

    align-items:
        center;

    justify-content:
        center;

    min-height:
        380px;

    padding:
        40px;

    border:
        1px solid #e3e8ed;

    border-radius:
        20px;

    background:
        #ffffff;

    text-align:
        center;

    box-sizing:
        border-box;
}


.nx-empty-icon {

    width:
        70px;

    height:
        70px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    margin-bottom:
        18px;

    border-radius:
        20px;

    background:
        #eef2f5;

    color:
        #718191;

    font-size:
        26px;
}


.nx-empty-profile h2 {

    margin:
        0 0 7px;

    color:
        #243b4e;

    font-size:
        20px;

    font-weight:
        800;
}


.nx-empty-profile p {

    margin:
        0;

    color:
        #7d8b98;

    font-size:
        12px;
}


/* ============================================================
   RESPONSIVE — TABLET
   ============================================================ */

@media (max-width: 1100px) {

    .nx-profile-page {

        padding:
            24px;
    }


    .nx-profile-hero-content {

        padding:
            32px;
    }


    .nx-info-grid {

        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-stats-grid {

        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-staff-overview {

        align-items:
            flex-start;

        flex-direction:
            column;
    }


    .nx-staff-meta {

        width:
            100%;

        flex:
            none;
    }

}


/* ============================================================
   RESPONSIVE — MOBILE
   ============================================================ */

@media (max-width: 720px) {

    .nx-profile-page {

        padding:
            16px 12px 40px;
    }


    .nx-profile-hero {

        border-radius:
            18px;
    }


    .nx-profile-hero-content {

        align-items:
            flex-start;

        flex-direction:
            column;

        padding:
            25px 22px;
    }


    .nx-profile-avatar {

        width:
            74px;

        height:
            74px;

        border-radius:
            19px;

        font-size:
            27px;
    }


    .nx-profile-identity h1 {

        font-size:
            27px;
    }


    .nx-profile-hero-action {

        width:
            100%;
    }


    .nx-edit-btn {

        width:
            100%;
    }


    .nx-card {

        padding:
            19px;

        border-radius:
            15px;
    }


    .nx-card-header {

        align-items:
            flex-start;

        flex-direction:
            column;

        margin-bottom:
            20px;
    }


    .nx-form-grid {

        grid-template-columns:
            1fr;
    }


    .nx-field-full {

        grid-column:
            auto;
    }


    .nx-info-grid,
    .nx-info-grid-three {

        grid-template-columns:
            1fr;
    }


    .nx-placement-grid {

        grid-template-columns:
            1fr;
    }


    .nx-stats-grid {

        grid-template-columns:
            1fr;
    }


    .nx-staff-meta {

        grid-template-columns:
            1fr;
    }


    .nx-staff-main {

        align-items:
            flex-start;
    }


    .nx-completion-footer {

        align-items:
            flex-start;

        flex-direction:
            column;
    }


    .nx-edit-actions {

        align-items:
            stretch;

        flex-direction:
            column;

        bottom:
            10px;
    }


    .nx-edit-buttons {

        width:
            100%;
    }


    .nx-secondary-btn,
    .nx-save-btn {

        flex:
            1;
    }

}


/* ============================================================
   SMALL MOBILE
   ============================================================ */

@media (max-width: 450px) {

    .nx-profile-role {

        align-items:
            flex-start;

        flex-direction:
            column;
    }


    .nx-profile-description {

        font-size:
            11px;
    }


    .nx-card-heading h2 {

        font-size:
            16px;
    }


    .nx-card-heading p {

        font-size:
            11px;
    }


    .nx-edit-buttons {

        flex-direction:
            column;
    }


    .nx-secondary-btn,
    .nx-save-btn {

        width:
            100%;
    }

}

/* ============================================================
   SKILL CATALOG FRONTEND
   ============================================================ */

.nx-skill-heading-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 9px;
}

.nx-skill-heading-row label {
    margin-bottom: 0;
}

.nx-request-skill-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 13px;
    border: 1px solid #dce4eb;
    border-radius: 9px;
    background: #ffffff;
    color: #17334b;
    font-size: 11px;
    font-weight: 750;
    cursor: pointer;
    transition: .2s ease;
}

.nx-request-skill-btn i {
    color: #ff6b5b;
}

.nx-request-skill-btn:hover {
    border-color: #ff6b5b;
    color: #ff6b5b;
    transform: translateY(-1px);
}

.nx-skills-display {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 9px;
    min-height: 72px;
    padding: 14px;
    border: 1px solid #dce4eb;
    border-radius: 11px;
    background: #f9fbfc;
    box-sizing: border-box;
}

.nx-skill-chip {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border: 1px solid #dce6ec;
    border-radius: 20px;
    background: #ffffff;
    color: #29445a;
    font-size: 11px;
    font-weight: 700;
    box-shadow: 0 3px 9px rgba(23,51,75,.05);
}

.nx-skill-chip i {
    color: #159c78;
    font-size: 10px;
}

.nx-skills-empty {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #8b98a4;
    font-size: 11px;
}

.nx-skill-help {
    display: block;
    margin-top: 7px;
    color: #8a98a5;
    font-size: 10px;
    line-height: 1.5;
}

.nx-skill-requests-field {
    margin-top: 2px;
}

.nx-skill-request-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.nx-skill-request-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 11px 13px;
    border: 1px solid #e0e7ed;
    border-radius: 10px;
    background: #ffffff;
}

.nx-skill-request-main {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 0;
}

.nx-skill-request-icon {
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 30px;
    border-radius: 8px;
    background: #edf8f4;
    color: #159c78;
}

.nx-skill-request-main strong {
    display: block;
    color: #30485a;
    font-size: 12px;
}

.nx-skill-request-main span {
    display: block;
    margin-top: 3px;
    color: #8a98a5;
    font-size: 10px;
}

.nx-skill-request-status {
    flex: 0 0 auto;
    padding: 5px 10px;
    border-radius: 20px;
    font-size: 9px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .35px;
}

.nx-request-pending {
    background: #fff6df;
    color: #a87915;
}

.nx-request-approved {
    background: #eaf8f2;
    color: #13865f;
}

.nx-request-rejected {
    background: #fff0ee;
    color: #d95548;
}

/* ============================================================
   REQUEST SKILL MODAL
   ============================================================ */

.nx-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background: rgba(17, 35, 50, .48);
    box-sizing: border-box;
}

.nx-skill-request-modal {
    width: min(560px, 100%);
    max-height: calc(100vh - 48px);
    overflow: auto;
    border-radius: 18px;
    background: #ffffff;
    box-shadow: 0 25px 70px rgba(13,31,46,.28);
}

.nx-modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
    padding: 22px 24px 18px;
    border-bottom: 1px solid #edf1f4;
}

.nx-modal-eyebrow {
    display: block;
    margin-bottom: 5px;
    color: #ff6b5b;
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 1px;
}

.nx-modal-header h3 {
    margin: 0;
    color: #17334b;
    font-size: 19px;
    font-weight: 800;
}

.nx-modal-header p {
    margin: 5px 0 0;
    color: #84919d;
    font-size: 11px;
}

.nx-modal-close {
    width: 32px;
    height: 32px;
    flex: 0 0 32px;
    border: 1px solid #e1e7ec;
    border-radius: 9px;
    background: #ffffff;
    color: #7d8b97;
    cursor: pointer;
}

.nx-modal-close:hover {
    border-color: #ff6b5b;
    color: #ff6b5b;
}

.nx-modal-body {
    padding: 22px 24px;
}

.nx-modal-field label,
.nx-modal-readonly-item span {
    display: block;
    margin-bottom: 7px;
    color: #637383;
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .55px;
}

.nx-modal-field .nx-input-wrap input {
    height: 44px;
}

.nx-modal-field small {
    display: block;
    margin-top: 6px;
    color: #8b98a4;
    font-size: 10px;
}

.nx-modal-readonly-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    margin-top: 18px;
}

.nx-modal-readonly-item {
    padding: 12px;
    border: 1px solid #e4eaef;
    border-radius: 10px;
    background: #f8fafb;
}

.nx-modal-readonly-item strong {
    display: block;
    color: #30485a;
    font-size: 12px;
}

.nx-pending-text {
    color: #a87915 !important;
}

.nx-modal-alert {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin-bottom: 15px;
    padding: 10px 12px;
    border-radius: 9px;
    font-size: 11px;
    line-height: 1.4;
}

.nx-modal-alert-error {
    background: #fff1ef;
    color: #c95045;
}

.nx-modal-alert-success {
    background: #edf9f4;
    color: #16815e;
}

.nx-modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 16px 24px;
    border-top: 1px solid #edf1f4;
    background: #fbfcfd;
}

.nx-submit-skill-btn {
    min-width: 145px;
}

@media (max-width: 600px) {
    .nx-skill-heading-row {
        align-items: flex-start;
        flex-direction: column;
    }

    .nx-request-skill-btn {
        width: 100%;
        justify-content: center;
    }

    .nx-skill-request-item {
        align-items: flex-start;
        flex-direction: column;
    }

    .nx-modal-readonly-grid {
        grid-template-columns: 1fr;
    }

    .nx-modal-footer {
        flex-direction: column;
    }

    .nx-modal-footer button {
        width: 100%;
    }
}


/* ============================================================
   ADD EXISTING SKILLS
   ============================================================ */

.nx-skill-actions {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex-wrap: wrap;
}

.nx-add-skill-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 13px;
    border: 1px solid #dce4eb;
    border-radius: 9px;
    background: #ffffff;
    color: #17334b;
    font-size: 11px;
    font-weight: 750;
    cursor: pointer;
    transition: .2s ease;
}

.nx-add-skill-btn i {
    color: #159c78;
}

.nx-add-skill-btn:hover {
    border-color: #159c78;
    color: #159c78;
    transform: translateY(-1px);
}

.nx-add-skill-modal {
    width: min(620px, 100%);
}

.nx-skill-catalog-search {
    position: relative;
    margin-bottom: 12px;
}

.nx-skill-catalog-search i {
    position: absolute;
    left: 13px;
    top: 50%;
    transform: translateY(-50%);
    color: #9aa8b4;
    font-size: 12px;
}

.nx-skill-catalog-search input {
    width: 100%;
    height: 42px;
    padding: 0 13px 0 35px;
    border: 1px solid #dce4eb;
    border-radius: 9px;
    background: #f9fbfc;
    color: #30485a;
    box-sizing: border-box;
    outline: none;
}

.nx-skill-catalog-search input:focus {
    border-color: #159c78;
    background: #ffffff;
}

.nx-skill-catalog-list {
    max-height: 310px;
    overflow-y: auto;
    border: 1px solid #e0e7ed;
    border-radius: 11px;
    background: #ffffff;
}

.nx-catalog-skill-row {
    position: relative;
    display: flex;
    align-items: center;
    gap: 11px;
    min-height: 54px;
    padding: 8px 13px;
    margin: 0;
    border-bottom: 1px solid #edf1f4;
    cursor: pointer;
    transition: .15s ease;
}

.nx-catalog-skill-row:last-child {
    border-bottom: 0;
}

.nx-catalog-skill-row:hover {
    background: #f8fbfa;
}

.nx-catalog-skill-row input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.nx-catalog-check {
    width: 20px;
    height: 20px;
    flex: 0 0 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #d3dfe6;
    border-radius: 6px;
    background: #ffffff;
    color: #ffffff;
    font-size: 10px;
}

.nx-catalog-skill-selected .nx-catalog-check {
    border-color: #159c78;
    background: #159c78;
}

.nx-catalog-skill-info {
    min-width: 0;
    flex: 1;
}

.nx-catalog-skill-info strong {
    display: block;
    color: #30485a;
    font-size: 12px;
}

.nx-catalog-skill-info small {
    display: block;
    margin-top: 2px;
    color: #8a98a5;
    font-size: 9px;
}

.nx-catalog-skill-disabled {
    cursor: default;
    background: #fafcfd;
    opacity: .72;
}

.nx-catalog-existing {
    flex: 0 0 auto;
    padding: 4px 8px;
    border-radius: 15px;
    background: #edf8f4;
    color: #13865f;
    font-size: 8px;
    font-weight: 800;
    text-transform: uppercase;
}

.nx-catalog-empty {
    min-height: 120px;
    justify-content: center;
    border: 1px solid #e0e7ed;
    border-radius: 11px;
}

.nx-selected-count {
    margin-right: auto;
    color: #81909c;
    font-size: 10px;
    font-weight: 700;
}

.nx-modal-footer-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

@media (max-width: 600px) {
    .nx-skill-actions {
        width: 100%;
        justify-content: stretch;
    }

    .nx-skill-actions button {
        flex: 1;
        justify-content: center;
    }

    .nx-modal-footer {
        align-items: stretch;
        flex-direction: column;
    }

    .nx-selected-count {
        margin-right: 0;
    }

    .nx-modal-footer-actions {
        width: 100%;
    }

    .nx-modal-footer-actions button {
        flex: 1;
    }
}

sp_widget.script:
(function() {



    /* =========================================================

       NEXORA — MY PROFILE

       ROLE-BASED PROFILE SERVER SCRIPT



       ROLES

       1. Student

       2. Placement Officer

       3. Placement Admin

       4. Interviewer



       NEW INSTANCE TABLE PREFIX

       x_snc_college_pl_0\_



       STUDENT TABLE

       x_snc_college_pl_0_student



       IMPORTANT

       ---------------------------------------------------------

       Student:

           Reads / updates ONLY own Student record.



       Placement Officer:

           Reads own sys_user profile.

           Read-only.



       Placement Admin:

           Reads own sys_user profile.

           Read-only.



       Interviewer:

           Reads own sys_user profile.

           Read-only.



       Staff users NEVER update the Student table.

       ========================================================= */





    /* =========================================================

       INITIAL DATA

       ========================================================= */



    data.profile = null;



    data.loading = false;



    data.error = '';



    data.success = false;



    data.message = '';



    data.action =

        input && input.action

            ? input.action

            : 'load';







    /* =========================================================

       CURRENT USER

       ========================================================= */



    var userId =

        gs.getUserID();





    if (!userId) {



        data.error =

            'Unable to identify the logged-in user.';



        return;

    }







    /* =========================================================

       CURRENT SERVICE NOW USER

       ========================================================= */



    var userGR =

        new GlideRecord('sys_user');





    if (!userGR.get(userId)) {



        data.error =

            'Unable to load the logged-in user information.';



        return;

    }







    /* =========================================================

       TABLE PREFIX

       ========================================================= */



    var STUDENT_TABLE =

        'x_snc_college_pl_0_student';



    var APPLICATION_TABLE =

        'x_snc_college_pl_0_application';



    var DRIVE_TABLE =

        'x_snc_college_pl_0_placement_drive';



    var INTERVIEW_TABLE =

        'x_snc_college_pl_0_interview';


    var SKILL_CATALOG_TABLE =

        'x_snc_college_pl_0_skills_catalog';


    var SKILL_REQUEST_TABLE =

        'x_snc_college_pl_0_skill_request';







    /* =========================================================

       ROLE DETECTION

       ========================================================= */



    function hasAnyRole(roleList) {



        for (

            var r = 0;

            r < roleList.length;

            r++

        ) {



            if (

                gs.hasRole(

                    roleList[r]

                )

            ) {



                return true;

            }

        }



        return false;

    }







    /*

     * We check both scoped and simple role names.

     *

     * This makes the widget safer if the role was created

     * differently in the new instance.

     */



    var isPlacementAdmin =

        hasAnyRole([



            'x_snc_college_pl_0.placement_admin',



            'placement_admin',



            'admin'



        ]);





    var isPlacementOfficer =

        hasAnyRole([



            'x_snc_college_pl_0.placement_officer',



            'placement_officer'



        ]);





    var isInterviewer =

        hasAnyRole([



            'x_snc_college_pl_0.interviewer',



            'interviewer'



        ]);





    var isStudent =

        hasAnyRole([



            'x_snc_college_pl_0.student_user',



            'student_user'



        ]);







    /* =========================================================

       ROLE PRIORITY



       Admin

          ↓

       Placement Officer

          ↓

       Interviewer

          ↓

       Student

       ========================================================= */



    var role = 'User';





    if (isPlacementAdmin) {



        role =

            'Placement Admin';



    }



    else if (isPlacementOfficer) {



        role =

            'Placement Officer';



    }



    else if (isInterviewer) {



        role =

            'Interviewer';



    }



    else if (isStudent) {



        role =

            'Student';

    }







    /* =========================================================

       ROLE FLAGS

       ========================================================= */



    data.isStudent =

        role === 'Student';



    data.isPlacementOfficer =

        role === 'Placement Officer';



    data.isPlacementAdmin =

        role === 'Placement Admin';



    data.isInterviewer =

        role === 'Interviewer';







    data.role =

        role;



    data.roleLabel =

        role;







    /* =========================================================

       COMMON USER INFORMATION

       ========================================================= */



    var userName =

        userGR.getDisplayValue(

            'name'

        ) || 'User';





    var userEmail =

        userGR.getValue(

            'email'

        ) || '';





    var username =

        userGR.getValue(

            'user_name'

        ) || '';





    var userActive =

        userGR.getValue(

            'active'

        ) === 'true';





    var userTitle =

        '';





    var userDepartment =

        '';





    var userMobile =

        '';





    /*

     * These are standard sys_user fields.

     *

     * isValidField() prevents errors if a field is not

     * available in your instance.

     */



    if (

        userGR.isValidField(

            'title'

        )

    ) {



        userTitle =

            userGR.getValue(

                'title'

            ) || '';

    }





    if (

        userGR.isValidField(

            'department'

        )

    ) {



        userDepartment =

            userGR.getDisplayValue(

                'department'

            ) || '';

    }





    if (

        userGR.isValidField(

            'mobile_phone'

        )

    ) {



        userMobile =

            userGR.getValue(

                'mobile_phone'

            ) || '';

    }







    /* =========================================================

       USER CREATED DATE

       ========================================================= */



    var userCreatedOn =

        '';





    if (

        userGR.isValidField(

            'sys_created_on'

        )

    ) {



        userCreatedOn =

            userGR.getDisplayValue(

                'sys_created_on'

            ) || '';

    }







    /* =========================================================

       STAFF STATISTICS DEFAULT

       ========================================================= */



    data.statistics = {



        drivesManaged: 0,



        applicationsReviewed: 0,



        studentsManaged: 0,



        interviewsAssigned: 0,



        interviewsCompleted: 0,



        pendingEvaluations: 0,



        selectedCandidates: 0,



        offers: 0



    };







    /* =========================================================

       STAFF STATISTICS

       ========================================================= */



    function getTableCount(

        tableName

    ) {



        var count = 0;





        var gr =

            new GlideRecord(

                tableName

            );





        if (

            !gr.isValid()

        ) {



            return 0;

        }





        gr.query();





        while (

            gr.next()

        ) {



            count++;

        }





        return count;

    }







    /* =========================================================

       STAFF PROFILE STATISTICS



       Used for:

       Placement Officer

       Placement Admin

       ========================================================= */



    function loadStaffStatistics() {





        /* -----------------------------------------------------

           STUDENTS

           ----------------------------------------------------- */



        data.statistics.studentsManaged =

            getTableCount(

                STUDENT_TABLE

            );







        /* -----------------------------------------------------

           DRIVES

           ----------------------------------------------------- */



        data.statistics.drivesManaged =

            getTableCount(

                DRIVE_TABLE

            );







        /* -----------------------------------------------------

           APPLICATIONS

           ----------------------------------------------------- */



        data.statistics.applicationsReviewed =

            getTableCount(

                APPLICATION_TABLE

            );







        /* -----------------------------------------------------

           INTERVIEWS

           ----------------------------------------------------- */



        data.statistics.interviewsAssigned =

            getTableCount(

                INTERVIEW_TABLE

            );







        /* -----------------------------------------------------

           COMPLETED / PENDING INTERVIEWS

           ----------------------------------------------------- */



        var interviewGR =

            new GlideRecord(

                INTERVIEW_TABLE

            );





        if (

            interviewGR.isValid()

        ) {



            interviewGR.query();





            while (

                interviewGR.next()

            ) {



                var interviewStatus =

                    String(

                        interviewGR.getDisplayValue(

                            'status'

                        ) || ''

                    ).toLowerCase();





                var result =

                    String(

                        interviewGR.getDisplayValue(

                            'result'

                        ) || ''

                    ).trim();





                var feedback =

                    String(

                        interviewGR.getValue(

                            'feedback'

                        ) || ''

                    ).trim();





                if (

                    interviewStatus ===

                        'completed' &&

                    (

                        result ||

                        feedback

                    )

                ) {



                    data.statistics

                        .interviewsCompleted++;



                }



                else {



                    data.statistics

                        .pendingEvaluations++;

                }

            }

        }







        /* -----------------------------------------------------

           SELECTED APPLICATIONS

           ----------------------------------------------------- */



        var selectedGR =

            new GlideRecord(

                APPLICATION_TABLE

            );





        if (

            selectedGR.isValid()

        ) {



            selectedGR.addQuery(

                'status',

                'Selected'

            );



            selectedGR.query();





            data.statistics.selectedCandidates =

                selectedGR.getRowCount();

        }







        /* -----------------------------------------------------

           OFFERS

           ----------------------------------------------------- */



        var offerTable =

            'x_snc_college_pl_0_offer_letter';





        var offerGR =

            new GlideRecord(

                offerTable

            );





        if (

            offerGR.isValid()

        ) {



            offerGR.query();





            data.statistics.offers =

                offerGR.getRowCount();

        }

    }







    /* =========================================================

       STUDENT RECORD

       ========================================================= */



    var studentGR =

        null;





    var studentFound =

        false;





    /*

     * Only Student users need the Student table.

     *

     * Staff users must NOT be forced to have a Student

     * record.

     */



    if (

        isStudent

    ) {



        studentGR =

            new GlideRecord(

                STUDENT_TABLE

            );





        if (

            !studentGR.isValid()

        ) {



            data.error =

                'Student table could not be loaded.';



            return;

        }





        /*

         * IMPORTANT:

         *

         * Student.user = logged-in sys_user

         */



        studentGR.addQuery(

            'user',

            userId

        );





        studentGR.setLimit(1);



        studentGR.query();





        if (

            !studentGR.next()

        ) {



            data.error =

                'Student profile not found for the logged-in user.';



            return;

        }





        studentFound =

            true;

    }







    /* =========================================================

       STUDENT UPDATE

       ========================================================= */


    /* =========================================================
       ADD EXISTING SKILLS FROM SKILL CATALOG
       ========================================================= */

    if (
        isStudent &&
        studentFound &&
        data.action === 'add_skills' &&
        input &&
        input.selectedSkillIds
    ) {

        var selectedSkillIds = input.selectedSkillIds;

        if (!Array.isArray(selectedSkillIds)) {
            data.success = false;
            data.error = 'Invalid skill selection.';
            return;
        }

        var validIds = [];
        var seenIds = {};

        for (var si = 0; si < selectedSkillIds.length; si++) {
            var selectedId = String(selectedSkillIds[si] || '').trim();
            if (!selectedId || seenIds[selectedId]) { continue; }
            seenIds[selectedId] = true;

            var selectedSkillGR = new GlideRecord(SKILL_CATALOG_TABLE);
            if (selectedSkillGR.get(selectedId)) {
                var activeValue = selectedSkillGR.getValue('active');
                if (activeValue === 'true' || activeValue === '1') {
                    validIds.push(selectedId);
                }
            }
        }

        if (!validIds.length) {
            data.success = false;
            data.error = 'No valid active Skill Catalog skill was selected.';
            return;
        }

        var existingValue = studentGR.getValue('skills') || '';
        var existingParts = existingValue ? existingValue.split(',') : [];
        var existingMap = {};
        var mergedIds = [];

        for (var ep = 0; ep < existingParts.length; ep++) {
            var existingId = String(existingParts[ep] || '').trim();
            if (existingId && !existingMap[existingId]) {
                existingMap[existingId] = true;
                mergedIds.push(existingId);
            }
        }

        var addedNames = [];

        for (var vi = 0; vi < validIds.length; vi++) {
            var newId = validIds[vi];
            if (!existingMap[newId]) {
                existingMap[newId] = true;
                mergedIds.push(newId);

                var nameGR = new GlideRecord(SKILL_CATALOG_TABLE);
                if (nameGR.get(newId)) {
                    addedNames.push(nameGR.getValue('skill_name') || nameGR.getDisplayValue());
                }
            }
        }

        if (!addedNames.length) {
            data.success = false;
            data.error = 'The selected skills are already in your profile.';
            return;
        }

        studentGR.setValue('skills', mergedIds.join(','));
        studentGR.update();

        data.success = true;
        data.skillsAdded = true;
        data.message = addedNames.join(', ') +
            (addedNames.length === 1 ? ' was added to your skills.' : ' were added to your skills.');
    }


    if (
        isStudent &&
        studentFound &&
        data.action === 'request_skill' &&
        input &&
        input.skillRequest
    ) {

        var requestedTerm =
            String(input.skillRequest.requestedTerm || '').trim();

        if (!requestedTerm) {
            data.success = false;
            data.error = 'Please enter the skill you want to request.';
            return;
        }

        if (requestedTerm.length > 100) {
            data.success = false;
            data.error = 'Skill name cannot exceed 100 characters.';
            return;
        }

        var skillRequestGR = new GlideRecord(SKILL_REQUEST_TABLE);

        if (!skillRequestGR.isValid()) {
            data.success = false;
            data.error = 'Skill Request table could not be loaded.';
            return;
        }

        skillRequestGR.addQuery('requested_by', studentGR.getUniqueValue());
        skillRequestGR.addQuery('requested_term', requestedTerm);
        skillRequestGR.addQuery('status', 'pending');
        skillRequestGR.setLimit(1);
        skillRequestGR.query();

        if (skillRequestGR.next()) {
            data.success = false;
            data.error = 'You already have a pending request for this skill.';
            return;
        }

        skillRequestGR.initialize();
        skillRequestGR.setValue('requested_term', requestedTerm);
        skillRequestGR.setValue('requested_by', studentGR.getUniqueValue());
        skillRequestGR.setValue('status', 'pending');

        var requestId = skillRequestGR.insert();

        if (!requestId) {
            data.success = false;
            data.error = 'Unable to create the skill request. Please try again.';
            return;
        }

        data.success = true;
        data.skillRequestCreated = true;
        data.skillRequestId = requestId;
        data.message = 'Skill request submitted successfully. It is now pending TPO approval.';
        return;
    }




    if (

        isStudent &&

        data.action === 'update_profile' &&

        input &&

        input.profile

    ) {





        var profile =

            input.profile;







        /* =====================================================

           STUDENT NAME



           Backend:

           student_name

           ===================================================== */



        if (

            typeof profile.fullName !==

                'undefined'

        ) {



            var updatedName =

                String(

                    profile.fullName

                ).trim();





            if (

                updatedName.length < 2

            ) {



                data.error =

                    'Please enter a valid student name.';



                return;

            }





            studentGR.setValue(

                'student_name',

                updatedName

            );

        }







        /* =====================================================

           EMAIL



           Backend:

           email

           ===================================================== */



        if (

            typeof profile.email !==

                'undefined'

        ) {



            var updatedEmail =

                String(

                    profile.email

                ).trim();





            if (

                updatedEmail &&

                /^[^\s@]+@[^\s@]+\\.[^\s@]+$/

                    .test(

                        updatedEmail

                    )

            ) {



                studentGR.setValue(

                    'email',

                    updatedEmail

                );



            }



            else {



                data.error =

                    'Please enter a valid email address.';



                return;

            }

        }







        /* =====================================================

           MOBILE NUMBER



           Backend:

           mobile_number

           ===================================================== */



        if (

            typeof profile.mobile !==

                'undefined'

        ) {



            var updatedMobile =

                String(

                    profile.mobile

                ).trim();





            var cleanMobile =

                updatedMobile.replace(

                    /[^0-9]/g,

                    ''

                );





            if (

                cleanMobile.length < 10 ||

                cleanMobile.length > 15

            ) {



                data.error =

                    'Please enter a valid mobile number.';



                return;

            }





            studentGR.setValue(

                'mobile_number',

                updatedMobile

            );

        }







        /* =====================================================

           GENDER



           Backend:

           gender

           ===================================================== */



        if (

            typeof profile.gender !==

                'undefined'

        ) {



            studentGR.setValue(

                'gender',

                String(

                    profile.gender

                ).trim()

