    function loadStaffProfile() {





        /*

         * Load staff statistics for all staff roles.

         */



        loadStaffStatistics();







        /* =====================================================

           ROLE DESCRIPTION

           ===================================================== */



        var roleDescription =

            '';





        if (

            isPlacementAdmin

        ) {



            roleDescription =

                'Manage placement operations, students, drives, applications and placement administration.';

        }



        else if (

            isPlacementOfficer

        ) {



            roleDescription =

                'Manage students, placement drives, applications and placement activities.';

        }



        else if (

            isInterviewer

        ) {



            roleDescription =

                'Manage assigned interviews, candidate evaluations and interview outcomes.';

        }







        /* =====================================================

           STAFF PROFILE COMPLETION

           ===================================================== */



        var staffFields = [



            userName,



            username,



            userEmail,



            userMobile,



            userTitle,



            userDepartment



        ];





        var staffCompleted =

            0;





        for (

            var s = 0;

            s < staffFields.length;

            s++

        ) {



            if (

                staffFields[s] &&

                String(

                    staffFields[s]

                ).trim() !== ''

            ) {



                staffCompleted++;

            }

        }





        var staffCompletion =

            Math.round(

                (

                    staffCompleted /

                    staffFields.length

                ) * 100

            );







        /* =====================================================

           FINAL STAFF PROFILE

           ===================================================== */



        data.profile = {



